import sys, random; sys.path.insert(0,'/workspace/project')
from modules.byte_program import *
random.seed(1)
def build():
    kind = random.randrange(4)
    if kind==0: return leaf(bytes([random.randrange(256) for _ in range(random.randrange(0,40))]))
    if kind==1: return concat(build(), build())
    if kind==2: return repeat(leaf(bytes([random.randrange(256) for _ in range(random.randrange(1,5))])), random.randrange(1,9))
    return concat_all([build() for _ in range(random.randrange(0,6))])
ok=True
for t in range(300):
    seq = build()
    if seq.n==0: continue
    data = materialize(seq,0,seq.n)
    if seq.n>0 and fingerprint(seq)['h'] != '%016x'%hash_bytes(data): ok=False; print('TOPHASH',t)
    for _ in range(20):
        lo=random.randrange(seq.n); hi=random.randrange(lo,seq.n+1)
        if materialize(seq,lo,hi)!=data[lo:hi]: ok=False;print('MAT FAIL',t,lo,hi,seq.tag)
        if range_hash(seq,lo,hi)!=(hi-lo, hash_bytes(data[lo:hi])): ok=False;print('HASH FAIL',t,lo,hi,seq.tag)
        if materialize(slice_seq(seq,lo,hi),0,hi-lo)!=data[lo:hi]: ok=False;print('SLICE FAIL',t,lo,hi,seq.tag)
        if fingerprint(slice_seq(seq,lo,hi))['h'] != '%016x'%range_hash(seq,lo,hi)[1]: ok=False; print('SLICEHASH',t)
print('random ok', ok)
w = ByteWindow(concat(build(), build()))
got=bytearray()
while w.pos < w.total:
    b,off,av = w.view(7)
    if av==0: break
    step = min(av, random.randrange(1,5))
    got += b[off:off+step]; w.advance(step)
print('window ok', bytes(got)==materialize(w.seq,0,w.seq.n))
